# Randomized parameter generator ensuring nontrivial instances
# Counts labeled binary circular sequences of length n with exactly k ones,
# where every length-w window has sum <= s.

def count_sequences(n, w, s, k):
    L = w - 1
    mask = (1 << L) - 1
    states = list(range(1 << L))
    pop = int.bit_count
    # Build allowed edges for each state: append bit b in {0,1} if window sum <= s
    allowed = [[] for _ in states]
    deg_bits = [set() for _ in states]
    for u in states:
        if pop(u) + 0 <= s:
            v0 = ((u << 1) & mask) | 0
            allowed[u].append((v0, 0))
            deg_bits[u].add(0)
        if pop(u) + 1 <= s:
            v1 = ((u << 1) & mask) | 1
            allowed[u].append((v1, 1))
            deg_bits[u].add(1)
    total = 0
    # DP over closed walks of length n starting and ending at the same state
    for start in states:
        dp = [[0] * (k + 1) for _ in states]
        dp[start][0] = 1
        for _ in range(n):
            new = [[0] * (k + 1) for _ in states]
            for u in states:
                row = dp[u]
                if not any(row):
                    continue
                for v, b in allowed[u]:
                    if b == 0:
                        for m in range(k + 1):
                            c = row[m]
                            if c:
                                new[v][m] += c
                    else:
                        for m in range(k):
                            c = row[m]
                            if c:
                                new[v][m + 1] += c
            dp = new
        total += dp[start][k]
    return total, deg_bits

